discrete LogicSubsystem
port:
    event input real StartSignal;
    event input real TaskCompletion;
    event input real InterruptRequest;
    event input real InterruptHandlingComplete;
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(StartSignal) then
            transition(State2);
        end;
        when receive(TaskCompletion) then
            transition(State1);
        end;
    end;

    state State2
        when entry() then
            statehold(0);
        end;
        when receive(TaskCompletion) then
            transition(State1);
        end;
        when receive(InterruptRequest) then
            transition(State3);
        end;
    end;

    state State3
        when entry() then
            statehold(0);
        end;
        when receive(InterruptHandlingComplete) then
            transition(State2);
        end;
    end;
end;
end;

discrete PeripheralInteractionSubsystem
port:
    event input real ReadWriteRequest;
    event input real DataTransferComplete;
    event input real ErrorOccurrence;
    event input real ErrorHandlingComplete;
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(ReadWriteRequest) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(0);
        end;
        when receive(DataTransferComplete) then
            transition(State1);
        end;
        when receive(ErrorOccurrence) then
            transition(State3);
        end;
    end;

    state State3
        when entry() then
            statehold(0);
        end;
        when receive(ErrorHandlingComplete) then
            transition(State1);
        end;
    end;
end;
end;

discrete ClockManagementSubsystem
port:
    event input real LowPowerModeDetected;
    event input real HighPerformanceModeDetected;
    event input real NormalOperationModeDetected;
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(LowPowerModeDetected) then
            transition(State2);
        end;
        when receive(HighPerformanceModeDetected) then
            transition(State3);
        end;
    end;

    state State2
        when entry() then
            statehold(0);
        end;
        when receive(NormalOperationModeDetected) then
            transition(State1);
        end;
    end;

    state State3
        when entry() then
            statehold(0);
        end;
        when receive(NormalOperationModeDetected) then
            transition(State1);
        end;
    end;
end;
end;

couple MCUSystem
import architectureModels.LogicSubsystem as Logic;
import architectureModels.PeripheralInteractionSubsystem as Peripheral;
import architectureModels.ClockManagementSubsystem as Clock;

part:
    Logic logicInstance;
    Peripheral peripheralInstance;
    Clock clockInstance;

connection:
    connect(logicInstance.TaskAssigned, peripheralInstance.ReadWriteRequest);
    connect(peripheralInstance.TaskCompletion, logicInstance.TaskCompletion);
    connect(logicInstance.ErrorOccurrence, peripheralInstance.ErrorOccurrence);
    connect(peripheralInstance.InterruptHandlingComplete, logicInstance.InterruptHandlingComplete);
    connect(logicInstance.PowerModeChange, clockInstance.PowerModeChange);
    connect(logicInstance.PerformanceModeChange, clockInstance.PerformanceModeChange);
    connect(clockInstance.OperationModeChange, logicInstance.OperationModeChange);
end;
